fn solve(input: Vec<char>) -> Vec<char> {
    // Get the first two characters (guaranteed to be digits)
    let first_char = input[0];
    let second_char = input[1];
    
    // Helper function to map digit char to its good count
    fn digit_to_good_count(c: char) -> u8 {
        match c {
            '0' => 2,
            '1' => 7,
            '2' => 2,
            '3' => 3,
            '4' => 3,
            '5' => 4,
            '6' => 2,
            '7' => 5,
            '8' => 1,
            '9' => 2,
            _ => 0, // This case won't occur due to problem constraints
        }
    }
    
    // Get the good counts
    let first_count = digit_to_good_count(first_char);
    let second_count = digit_to_good_count(second_char);
    
    // Compute product (guaranteed to fit in u8 and be between 1 and 49)
    let product = (first_count as u16) * (second_count as u16);
    
    // Convert product to string and then to Vec<char>
    let mut result: Vec<char> = product.to_string().chars().collect();
    
    // Append newline character
    result.push('\n');
    
    result
}